"""Public, static app information. Does not read credentials or account data."""
from starlette.responses import Response

ASSETS = {'/': ('<!doctype html>\n<html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Google Ads med en anslutning du styr · VicsGoogleAdsMCP</title><meta name="description" content="Information om VicsGoogleAdsMCP, hur anslutningen till Google Ads fungerar och hur uppgifter behandlas."><link rel="stylesheet" href="/style.css"><meta name="theme-color" content="#12382f"></head>\n<body><a class="skip" href="#main">Hoppa till innehåll</a><header><a class="brand" href="/"><span class="mark" aria-hidden="true">V</span>VicsGoogleAdsMCP</a><nav aria-label="Huvudmeny"><a href="/">Om appen</a><a href="/privacy.html">Integritet</a><a href="/terms.html">Villkor</a></nav></header><main id="main">\n<section class="hero"><div><p class="eyebrow">APPINFORMATION</p><h1>Dina annonskonton.<br>En tydligare arbetsyta.</h1><p class="lead">VicsGoogleAdsMCP kopplar behöriga användares Google Ads-konton till en MCP-kompatibel AI-assistent, till exempel Claude. Läs rapporter, analysera kampanjer och förbered ändringar i samma arbetsflöde.</p><div class="actions"><a class="button" href="/privacy.html">Så hanteras dina uppgifter <span aria-hidden="true">↗</span></a><a href="mailto:viktorstrindin93@gmail.com">Kontakta ansvarig</a></div></div>\n<aside class="flow" aria-label="Anslutningens dataflöde"><p class="eyebrow">SÅ HÄNGER DET IHOP</p><div><b>01</b><span>Google Ads<small>Konton du har behörighet till</small></span></div><div><b>02</b><span>Din MCP-anslutning<small>Drivs i operatörens Google Cloud-projekt</small></span></div><div><b>03</b><span>Din AI-assistent<small>Begär och visar de resultat du använder</small></span></div><p class="flow-note">Google-inloggningen ger åtkomst. Den här informationssidan innehåller ingen inloggning till annonskonton.</p></aside></section>\n<section class="overview"><p class="eyebrow">VAD APPEN GÖR</p><div class="columns"><article><span class="number">01 / LÄS</span><h2>Förstå resultaten</h2><p>Hämta konto- och kampanjinformation samt rapporter om exempelvis kostnad, klick och konverteringar från Google Ads.</p></article><article><span class="number">02 / FÖRBERED</span><h2>Granska före ändring</h2><p>Skrivfunktioner kan förbereda avgränsade ändringar. I läget med obligatoriskt godkännande krävs ett separat godkännande innan de genomförs.</p></article><article><span class="number">03 / STYR</span><h2>Behåll kontrollen</h2><p>Åtkomst begränsas av ditt Google-kontos behörigheter och serverns inställningar. Du kan återkalla Google-åtkomsten när du vill.</p></article></div></section>\n<section class="note"><div><p class="eyebrow">FÖR BEHÖRIGA ANVÄNDARE</p><h2>En egen anslutning till ditt arbetsflöde.</h2></div><p>Appen är avsedd för operatören och särskilt behöriga användare som arbetar med egna eller kunders annonskonton. Den här webbplatsen är offentlig appinformation; den ger inte besökare åtkomst till MCP-servern eller Google Ads.</p></section>\n<section class="contact"><h2>Frågor om appen eller dina uppgifter?</h2><p>Kontakt för drift, support och integritetsfrågor: <a href="mailto:viktorstrindin93@gmail.com">viktorstrindin93@gmail.com</a>.</p><p>Läs <a href="/privacy.html">integritetspolicyn</a> och <a href="/terms.html">användningsvillkoren</a> innan du ansluter ditt konto.</p></section>\n</main><footer><a class="brand" href="/">VicsGoogleAdsMCP</a><p>Ett fristående verktyg för Google Ads. Inte en officiell produkt från Google eller Anthropic.</p><nav aria-label="Sidfot"><a href="/privacy.html">Integritetspolicy</a><a href="/terms.html">Användningsvillkor</a><a href="mailto:viktorstrindin93@gmail.com">Kontakt</a></nav><small>Uppdaterad 20 oktober 2026</small></footer></body></html>', 'text/html'), '/privacy.html': ('<!doctype html>\n<html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Integritetspolicy · VicsGoogleAdsMCP</title><meta name="description" content="Information om VicsGoogleAdsMCP, hur anslutningen till Google Ads fungerar och hur uppgifter behandlas."><link rel="stylesheet" href="/style.css"><meta name="theme-color" content="#12382f"></head>\n<body><a class="skip" href="#main">Hoppa till innehåll</a><header><a class="brand" href="/"><span class="mark" aria-hidden="true">V</span>VicsGoogleAdsMCP</a><nav aria-label="Huvudmeny"><a href="/">Om appen</a><a href="/privacy.html">Integritet</a><a href="/terms.html">Villkor</a></nav></header><main id="main">\n<article class="document"><p class="eyebrow">DINA UPPGIFTER</p><h1>Integritetspolicy</h1><p class="lead">Den här policyn beskriver hur VicsGoogleAdsMCP använder uppgifter när du ansluter Google Ads till en AI-assistent.</p><p class="date">Senast uppdaterad: 20 oktober 2026</p>\n<h2>1. Appen och kontakt</h2><p>VicsGoogleAdsMCP är en fristående, självhostad MCP-anslutning. För frågor om drift, behandling av uppgifter eller radering, kontakta appens operatör på <a href="mailto:viktorstrindin93@gmail.com">viktorstrindin93@gmail.com</a>. När ett kundkonto används ansvarar även den organisation som gett användaren uppdraget för sin behandling av kundens uppgifter.</p>\n<h2>2. Vilka uppgifter behandlas?</h2><ul><li><strong>Google-identitet:</strong> grundläggande profiluppgifter, e-postadress och identifierare som används för att autentisera dig.</li><li><strong>Anslutningsuppgifter:</strong> OAuth-token och sessionsuppgifter som behövs för att upprätthålla anslutningen. Appen tar inte emot ditt Google-lösenord.</li><li><strong>Google Ads-data:</strong> uppgifter som efterfrågas genom verktygen, till exempel kontoidentifierare, kontonamn, kampanjer, budgetar och resultatmått såsom kostnad, klick och konverteringar.</li><li><strong>Ändringsunderlag:</strong> planerade ändringar, godkännanden och körningsstatus när skrivfunktioner används.</li><li><strong>Driftuppgifter:</strong> tekniska loggar, felinformation och uppgifter om anrop som behövs för säkerhet och felsökning.</li></ul>\n<h2>3. Varför används uppgifterna?</h2><p>Uppgifterna används för att identifiera behöriga användare, hämta begärda rapporter, besvara användarens frågor och förbereda eller genomföra tillåtna ändringar. Anslutningsuppgifter används även för att hålla inloggningen fungerande. Driftuppgifter används för att underhålla tjänsten och utreda fel.</p><p>Du ska endast ansluta konton och begära data som du har rätt att använda. Denna anslutning är inte avsedd för att samla in känsliga personuppgifter eller exportera kundlistor.</p>\n<h2>4. Var behandlas och lagras uppgifterna?</h2><p>MCP-servern körs i operatörens Google Cloud-projekt. Firestore används för beständig anslutningsinformation och ändringsunderlag när detta är konfigurerat. Hemligheter hanteras via Google Cloud Secret Manager. Åtkomst styrs med behörigheter i Google Cloud. OAuth-lagringen har stöd för kryptering av innehållet.</p><p>Information som ett MCP-verktyg returnerar skickas till den anslutna klienten. Om du använder Claude behandlas den informationen även av Anthropic enligt villkoren och datainställningarna för ditt Claude-konto. Det innebär att självhosting inte håller alla verktygsresultat utanför AI-leverantören.</p>\n<h2>5. Delning och användning av Google-data</h2><p>Uppgifter behandlas av Google för Google Ads och infrastrukturen samt av den AI-klient och leverantör som användaren väljer för den begärda funktionen. VicsGoogleAdsMCP säljer inte Google-användardata och använder dem inte för annonsinriktning eller för att träna generella AI-modeller. AI-klientens egen behandling styrs av dess avtal och inställningar.</p><p>VicsGoogleAdsMCP:s användning och överföring av information från Google API:er ska följa <a href="https://developers.google.com/terms/api-services-user-data-policy">Google API Services User Data Policy</a>, inklusive kraven för Limited Use. Operatören får endast använda uppgifterna för den funktion du begär och för nödvändig drift, säkerhet och support.</p>\n<h2>6. Lagringstid och radering</h2><p>Anslutningsuppgifter behövs medan anslutningen används. Du kan återkalla åtkomsten i <a href="https://myaccount.google.com/connections">ditt Google-kontos anslutningar</a> och koppla från MCP-anslutningen i din AI-klient. Återkallad åtkomst stoppar framtida auktoriserad hämtning men raderar inte automatiskt uppgifter som redan har sparats i en chatt eller i serverns lagring.</p><p>Kontakta operatören för att begära radering av lagrade anslutningsuppgifter och ändringsunderlag. Ändringsunderlag har normalt en teknisk raderingsmarkering efter 30 dagar; automatisk radering förutsätter att databasens TTL-funktion är aktiverad. Underlag för oklara eller misslyckade ändringar kan behöva behållas för utredning. Driftloggar följer projektets inställda lagringstider. Chattar och data hos din AI-leverantör hanteras separat där.</p>\n<h2>7. Dina val och rättigheter</h2><p>Du kan avstå från att ansluta ett konto, återkalla åtkomst eller begära information, rättelse och radering genom kontaktadressen ovan. Ange vilket konto och vilken begäran det gäller, men skicka inte lösenord eller token. Identiteten kan behöva kontrolleras innan uppgifter lämnas ut eller raderas. Om dataskyddslagstiftning är tillämplig kan du även kontakta relevant tillsynsmyndighet, exempelvis Integritetsskyddsmyndigheten i Sverige.</p>\n<h2>8. Den här informationswebbplatsen</h2><p>Webbplatsen visar endast appinformation, policy och villkor. Den innehåller inga annonsrapporter, inga formulär för Google-inloggning och ingen egen analys- eller reklamkod. Den är hostad i operatörens Google Cloud-projekt. Hosting-leverantören kan behandla tekniska besöksuppgifter för leverans, drift och säkerhet enligt sina villkor.</p>\n<h2>9. Ändringar</h2><p>Policyn uppdateras när appens funktioner eller behandling förändras. Datumet ovan visar den senaste versionen. Frågor skickas till <a href="mailto:viktorstrindin93@gmail.com">viktorstrindin93@gmail.com</a>.</p></article>\n</main><footer><a class="brand" href="/">VicsGoogleAdsMCP</a><p>Ett fristående verktyg för Google Ads. Inte en officiell produkt från Google eller Anthropic.</p><nav aria-label="Sidfot"><a href="/privacy.html">Integritetspolicy</a><a href="/terms.html">Användningsvillkor</a><a href="mailto:viktorstrindin93@gmail.com">Kontakt</a></nav><small>Uppdaterad 20 oktober 2026</small></footer></body></html>', 'text/html'), '/terms.html': ('<!doctype html>\n<html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Användningsvillkor · VicsGoogleAdsMCP</title><meta name="description" content="Information om VicsGoogleAdsMCP, hur anslutningen till Google Ads fungerar och hur uppgifter behandlas."><link rel="stylesheet" href="/style.css"><meta name="theme-color" content="#12382f"></head>\n<body><a class="skip" href="#main">Hoppa till innehåll</a><header><a class="brand" href="/"><span class="mark" aria-hidden="true">V</span>VicsGoogleAdsMCP</a><nav aria-label="Huvudmeny"><a href="/">Om appen</a><a href="/privacy.html">Integritet</a><a href="/terms.html">Villkor</a></nav></header><main id="main">\n<article class="document"><p class="eyebrow">ANVÄNDNING AV APPEN</p><h1>Användningsvillkor</h1><p class="lead">För behöriga användare av VicsGoogleAdsMCP.</p><p class="date">Senast uppdaterad: 20 oktober 2026</p>\n<h2>1. Ändamål och behörighet</h2><p>VicsGoogleAdsMCP förmedlar begäranden mellan en MCP-kompatibel klient och Google Ads. Använd bara konton som du har rätt att företräda. Åtkomst förutsätter Google-behörighet och att serverns åtkomstregler tillåter åtgärden.</p>\n<h2>2. Läsning och ändringar</h2><p>Rapporter och förslag ska granskas innan de ligger till grund för beslut. Tillgängliga skrivfunktioner beror på serverns konfiguration. Validering eller en förhandsvisning skapar i sig ingen kampanj. När en ändring godkänns och genomförs kan den påverka ett verkligt annonskonto.</p><p>Nya kampanjer som skapas av appens funktion för pausade sökkampanjer skapas pausade. Aktivering hanteras separat. Granska konto, belopp, valuta, innehåll och förväntad effekt före varje godkännande. Googles regler för genomsnittlig dagsbudget och faktisk debitering gäller även när appen har egna budgetgränser.</p>\n<h2>3. Användarens ansvar</h2><p>Du ansvarar för dina instruktioner, godkännanden, annonsinnehåll och kostnader på de konton du förvaltar. Skydda inloggning och godkännandeuppgifter. Använd inte appen för att kringgå behörigheter eller bryta mot Google Ads policyer eller tillämplig lag.</p>\n<h2>4. Tillgänglighet och begränsningar</h2><p>Appen tillhandahålls utan löfte om oavbruten tillgänglighet eller viss annonseringseffekt. API:er, behörigheter och externa tjänster kan ändras. Vid ett oklart körningsresultat ska kontot och statusen kontrolleras innan samma ändring skickas igen. Dessa villkor begränsar inte rättigheter som inte får avtalas bort enligt tillämplig lag.</p>\n<h2>5. Externa tjänster och integritet</h2><p>Google Ads, Google Cloud och vald AI-klient omfattas av sina respektive villkor. Appen är inte en officiell Google- eller Anthropic-produkt. Läs <a href="/privacy.html">integritetspolicyn</a> för information om behandling av uppgifter.</p>\n<h2>6. Avsluta användningen och få hjälp</h2><p>Du kan sluta använda anslutningen, koppla från den i AI-klienten och återkalla Google-åtkomsten. Support och frågor om villkoren: <a href="mailto:viktorstrindin93@gmail.com">viktorstrindin93@gmail.com</a>.</p></article>\n</main><footer><a class="brand" href="/">VicsGoogleAdsMCP</a><p>Ett fristående verktyg för Google Ads. Inte en officiell produkt från Google eller Anthropic.</p><nav aria-label="Sidfot"><a href="/privacy.html">Integritetspolicy</a><a href="/terms.html">Användningsvillkor</a><a href="mailto:viktorstrindin93@gmail.com">Kontakt</a></nav><small>Uppdaterad 20 oktober 2026</small></footer></body></html>', 'text/html'), '/style.css': ('\n:root{--ink:#17352e;--muted:#50685f;--paper:#f6f7f1;--line:#d9dfd3;--accent:#d1ed81}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.65}a{color:inherit;text-underline-offset:4px}a:hover{color:#487027}a:focus-visible{outline:3px solid #6e911f;outline-offset:5px}.skip{position:absolute;top:-80px;left:16px;background:white;padding:10px;z-index:3}.skip:focus{top:12px}header,main,footer{max-width:1200px;margin:auto}header{padding:28px 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:24px}.brand{display:flex;align-items:center;gap:10px;font-weight:750;letter-spacing:-.5px;text-decoration:none}.mark{display:grid;place-items:center;background:var(--ink);color:var(--accent);border-radius:10px;width:34px;height:34px}nav{display:flex;gap:24px;font-size:14px}nav a{text-decoration:none}main{padding:0 40px}.hero{padding:86px 0 76px;display:grid;grid-template-columns:1.2fr 1fr;gap:72px;align-items:center}.eyebrow{font-size:11px;font-weight:750;letter-spacing:2px;margin:0 0 20px;color:var(--muted)}h1,h2{line-height:1.12;letter-spacing:-1.7px;font-weight:620}h1{font-size:clamp(36px,4.5vw,57px);margin:0 0 28px}.lead{color:var(--muted);font-size:18px;line-height:1.75}.actions{display:flex;align-items:center;gap:24px;flex-wrap:wrap;margin-top:28px;font-size:14px}.button{background:var(--ink);color:white;border-radius:8px;padding:14px 18px;text-decoration:none;display:flex;gap:18px}.button:hover{background:#284e40;color:white}.flow{background:var(--ink);color:#f3f8eb;border-radius:22px;padding:30px}.flow .eyebrow{color:var(--accent)}.flow>div{display:flex;gap:18px;padding:20px 0;border-bottom:1px solid #496155}.flow b{color:var(--accent);font-size:12px;padding-top:4px}.flow span{font-size:21px;line-height:1.4}.flow small{display:block;font-size:13px;color:#c1d0c6;margin-top:7px}.flow-note{font-size:12px;color:#c1d0c6;margin:22px 0 0}.overview{padding:44px 0 64px;border-top:1px solid var(--line)}.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}.number{font-size:11px;color:var(--muted);letter-spacing:1px}h2{font-size:27px;letter-spacing:-.7px}.columns p,.contact p{color:var(--muted)}.note{border-radius:16px;background:#e8eedc;padding:36px;display:grid;grid-template-columns:1fr 1fr;gap:55px}.note h2{margin:0}.note p:last-child{margin:0}.contact{padding:56px 0 72px}.contact h2{font-size:24px}footer{padding:32px 40px;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}footer nav{margin:20px 0}footer small{font-size:11px}.document{max-width:780px;padding:70px 0 80px;margin:0 auto}.document h1{font-size:48px}.document h2{font-size:25px;margin:40px 0 16px}.document p,.document li{color:#40594f}.document li{margin:12px 0}.date{font-size:13px}.document .lead{font-size:19px}.document a{overflow-wrap:anywhere}@media(max-width:760px){header{padding:20px;flex-wrap:wrap}nav{gap:18px}main{padding:0 22px}.hero{grid-template-columns:1fr;padding:48px 0;gap:32px}.columns{grid-template-columns:1fr;gap:24px}.columns h2{margin:12px 0}.note{grid-template-columns:1fr;gap:20px;padding:26px}.document{padding-top:44px}.document h1{font-size:38px}footer{padding:28px 22px}.contact a{overflow-wrap:anywhere}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n', 'text/css')}

def register_public_site_routes(mcp):
    for path, (body, media_type) in ASSETS.items():
        def make_handler(content, content_type):
            async def serve(request):
                return Response(content, media_type=content_type, headers={
                    "Cache-Control": "public, max-age=300",
                    "X-Content-Type-Options": "nosniff",
                    "Content-Security-Policy": "default-src 'none'; style-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'",
                })
            return serve
        mcp.custom_route(path, methods=["GET"])(make_handler(body, media_type))
